const main=document.querySelector('main'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let DATA,items=[],civs=[],sources={},state,storage,liveMap=null,markers=[],mapIndex=FRAMES.indexOf(850),currentType='all',quizAnswers={},toastTimer;
const escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const CIV_COLORS={egypt:'#e6b450',greece:'#4fa3e3',rome:'#e0564f',china:'#f08a3c',umayyad:'#efe6cf',abbasid:'#a48cff',andalus:'#2ec4b0','first-saudi':'#5cc172',persia:'#d16ba5',ottoman:'#ff6b6b',saba:'#b5d65a',nabataea:'#ee8aa6',mamluks:'#f2c14e',mongols:'#64b5f6',rashidun:'#4dd0e1',byzantine:'#e8746a',sasanian:'#c49a6c',fatimids:'#f6d55c',ayyubids:'#ffb74d',seljuks:'#81c784',safavids:'#4db6ac',mughals:'#f48fb1','second-saudi':'#43a047','saudi-kingdom':'#2e7d32',parthians:'#ba68c8',almohads:'#26a69a',mali:'#ffca28',ming:'#ef5350',mesopotamia:'#d4a373',phoenicia:'#b07cd8',maurya:'#ff8a65',timurids:'#4fc3f7',aztecs:'#66bb6a',inca:'#ffb300'};const civColor=id=>CIV_COLORS[id]||'#d6b477';
const ERAS=[[-500,'العالم القديم'],[500,'العصر الكلاسيكي'],[1250,'العصور الإسلامية'],[1500,'عصر المغول والمماليك'],[Infinity,'بدايات العصر الحديث']];const eraName=y=>ERAS.find(e=>y<e[0])[1];
const KINDS={battle:'معركة أو حصار',founding:'تأسيس وبناء',political:'تحول سياسي'};
const NOJOIN='اأإآٱدذرزوؤةىء';const kashida=t=>t.split(' ').map(w=>{if(w.length<5||/[^ء-ي]/.test(w))return w;const mid=Math.floor(w.length/2);for(const i of [mid,mid-1,mid+1,mid-2]){if(i>0&&i<w.length-1&&!NOJOIN.includes(w[i])&&/[ء-ي]/.test(w[i+1]))return w.slice(0,i+1)+'ـ'+w.slice(i+1)}return w}).join(' ');
const yearsBetween=(a,b)=>{let d=b-a;if(a<0&&b>0)d-=1;return d};
const eraGroups=()=>{const g=[];FRAMES.forEach((y,i)=>{const n=eraName(y),l=g[g.length-1];if(l&&l.name===n){l.to=i}else g.push({name:n,from:i,to:i})});return g};
const ICON_LAYERS='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 2 8l10 5 10-5-10-5Z"/><path d="m2 13 10 5 10-5"/><path d="m2 17.5 10 5 10-5" opacity=".55"/></svg>';
let coachSeen=(()=>{try{return localStorage.getItem('atlas-coach-v1')==='1'}catch{return false}})();
function hideCoach(save){const c=document.getElementById('ax-coach');if(c&&!c.hidden){c.hidden=true;if(save!==false){coachSeen=true;try{localStorage.setItem('atlas-coach-v1','1')}catch{}}}}
function togglePanel(force){const p=document.getElementById('ax-panel'),b=document.getElementById('ax-layers-btn');if(!p||!b)return;const open=force??p.hidden;p.hidden=!open;b.setAttribute('aria-expanded',String(open));b.classList.toggle('active',open)}
const certLevel=x=>{const c=x?.certainty||'';return /تقريب/.test(c)?['approx','تاريخ أو موضع تقريبي']:/^موثق/.test(c)?['sure','موثق بالمصادر']:['mixed','التوثيق متفاوت بين الأقسام']};
const types={civilization:'حضارة ودولة',city:'مدينة',person:'شخصية',event:'حدث',science:'علوم واكتشافات'};
try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error()}}}state=readStore(storage);
const byId=id=>items.find(x=>x.id===id);
const href=id=>`#/topic/${encodeURIComponent(id)}`;
const sourceLinks=ids=>`<ul class="source-list">${[...new Set(ids||[])].map((id,i)=>sources[id]?`<li id="src-${escape(id)}"><b class="src-n">${i+1}</b><a href="${escape(sources[id].url)}" target="_blank" rel="noopener noreferrer">${escape(sources[id].title)} ↗</a><small>${escape(sources[id].type||'مصدر تاريخي')} · اطلعنا عليه في 12 أكتوبر 2026</small></li>`:'').join('')}</ul>`;
function persist(){const ok=saveStore(storage,state);if(!ok)toast('تعذر حفظ التقدم على هذا المتصفح؛ سيبقى لهذه الجلسة فقط.');return ok}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3800)}
const head=(title,description,eyebrow='اكتشف. اربط. افهم.')=>`<div class="container page-head reveal"><div class="breadcrumb"><a href="#/">الرئيسية</a> / ${escape(title)}</div><div class="eyebrow">${eyebrow}</div><h1>${escape(title)}</h1><p>${escape(description)}</p></div>`;
const figure=x=>x.image?`<figure class="photo"><img src="${escape(x.image.src)}" alt="${escape(x.image.caption)}" loading="lazy" decoding="async" onerror="this.closest('figure').remove()"><figcaption>${escape(x.image.caption)} <a class="cr" href="${escape(x.image.page)}" target="_blank" rel="noopener" title="${escape(x.image.author)} · ${escape(x.image.license)}" aria-label="حقوق الصورة: ${escape(x.image.author)}، ${escape(x.image.license)}">©</a></figcaption></figure>`:'';
function card(c){return `<a class="civ-card ${c.image?'has-photo':''}" href="${href(c.id)}"${c.image?` style="--photo:url('${escape(c.image.src)}')"`:''}>${c.image?'<span class="card-photo" aria-hidden="true"></span>':motif(c.id)}<small>${escape(c.region)}</small><h3>${escape(c.title)}</h3><small>${escape(c.periodLabel)}</small></a>`}
function result(x){return `<a class="result-card" href="${href(x.id)}"><span class="badge">${types[x.type]||'موضوع'}</span><h3>${escape(x.title)}</h3><p>${escape(clip(x.summary,170))}</p></a>`}
function clip(t,n){if(t.length<=n)return t;const c=t.slice(0,n),i=c.lastIndexOf(' ');return (i>n*.6?c.slice(0,i):c).replace(/[،,.؛:]+$/,'')+'…'}
function sectionTitle(n,title,desc,link,label){return `<div class="section-head"><div><div class="eyebrow">${n}</div><h2>${title}</h2><p>${desc}</p></div>${link?`<a class="text-link" href="${link}">${label} ←</a>`:''}</div>`}
function journeyCard(j){const p=state.journeys[j.id]||{};let done=Array.isArray(p.done)?p.done.length:0;return `<a href="#/journey/${j.id}" class="journey-card"><span class="num">${String(JOURNEYS.indexOf(j)+1).padStart(2,'0')}</span><h3>${j.title}</h3><p>${j.subtitle}</p><span class="muted">${j.steps.length} محطات · أسئلة فهم · حفظ محلي</span><div class="progress-track"><span style="width:${done/j.steps.length*100}%"></span></div><span class="text-link">${done===j.steps.length?'راجع الرحلة':done?'تابع رحلتك':'ابدأ الرحلة'} ← <small>${done}/${j.steps.length}</small></span></a>`}
function warmMap(){const c=navigator.connection;if(c&&(c.saveData||/2g/.test(c.effectiveType||'')))return;const t=mountToken;setTimeout(()=>{if(t!==mountToken||window.maplibregl)return;const go=()=>['maplibre-gl.js','maplibre-gl.css','land.geojson','water.geojson','physical.geojson','geo-labels.json'].forEach(f=>fetch('assets/'+f).catch(()=>{}));window.requestIdleCallback?requestIdleCallback(go,{timeout:3000}):go()},2500)}
function home(){main.innerHTML=`<section class="hero"><div class="hero-content reveal"><div class="eyebrow">أطلس التاريخ التفاعلي <span class="latin"> / ATLAS</span></div><h1>التاريخ ليس مجرد أحداث…<br>إنه عالم ينتظر أن <em>تكتشفه.</em></h1><p>اعبر العصور، استكشف الحضارات، وافهم كيف ارتبطت قصص الإنسان بالأماكن التي عاش فيها.</p><div class="actions"><a class="primary" href="#/encyclopedia">ابدأ الاستكشاف <span>←</span></a><a class="secondary" href="#/atlas">استكشف الخريطة <span>⌖</span></a></div></div><div class="hero-bottom"><span></span><span class="coords" dir="ltr">A JOURNEY THROUGH HUMAN HISTORY</span></div></section><div class="intro-line"><span><b>${String(civs.length).padStart(2,'0')}</b> موضوعات حضارية</span><span><b>${String(FRAMES.length).padStart(2,'0')}</b> لقطات زمنية</span><span><b>${String(JOURNEYS.length).padStart(2,'0')}</b> رحلات تعليمية</span><span>كل موضوع يبدأ بسؤال وينتهي بفهم.</span></div>
<section class="container section">${sectionTitle('01 / عبر الزمن','كل عصر… نافذة إلى عالم آخر.','اختر حقبة، ثم تتبع الحضارات والمواقع المرتبطة بها.')}<div class="era-list">${[['01','العالم القديم','1750 — 1400 ق.م',-1750],['02','العصر الكلاسيكي','400 ق.م — 117 م',-100],['03','العصور الإسلامية','632 — 1000 م',650],['04','عصر المغول والمماليك','1300 م',1300],['05','بدايات حديثة','1750 م',1750]].map(x=>`<a class="era" href="#/atlas?year=${x[3]}"><span class="era-number">${x[0]}</span><strong>${x[1]}</strong><small>${x[2]} ←</small></a>`).join('')}</div></section>
<section class="container section" style="padding-top:15px">${sectionTitle('02 / قصص الحضارات','حضارات صنعت التاريخ',`${civs.length} بابًا إلى السياسة والفن والمعرفة والحياة اليومية.`,'#/encyclopedia','الموسوعة كاملة')}<div class="civ-grid">${['abbasid','rashidun','umayyad','andalus','ottoman','egypt','rome','first-saudi'].map(byId).filter(Boolean).map(card).join('')}</div><div class="more-row"><a class="secondary" href="#/encyclopedia?type=civilization">عرض كل الحضارات (${civs.length}) ←</a></div></section>
<section class="map-feature section"><div class="container">${sectionTitle('03 / المكان والزمان','العالم عبر الزمن','حرّك الزمن. اختر مدينة. اكتشف القصة.','#/atlas','افتح الأطلس')} ${mapShell(false)}</div></section>
<section class="container section">${sectionTitle('04 / نقاط التحول','أحداث غيّرت العالم','افهم الحدث في سياقه: أين وقع، وماذا تغير بعده؟','#/encyclopedia?type=event','كل الأحداث')}<div class="events-list">${items.filter(x=>x.type==='event').slice(0,3).sort((a,b)=>a.start-b.start).map(x=>`<a class="event-card" href="${href(x.id)}"><span class="date">${escape(x.periodLabel)}</span><h3>${escape(x.title)}</h3><p>${escape(x.summary.slice(0,140))}…</p><span class="text-link">اكتشف الحدث ←</span></a>`).join('')}</div></section>
<section class="container section" style="padding-top:10px">${sectionTitle('05 / تعلّم بالاستكشاف','رحلتك أعمق من قراءة مقال','محطات قصيرة، روابط على الخريطة، وأسئلة تتأكد بها من فهمك.','#/journeys','جميع الرحلات')}<div class="journey-grid">${JOURNEYS.filter(j=>j.featured).slice(0,4).map(journeyCard).join('')}</div></section>
<section class="container section"><div class="city-feature"><div class="city-art">${citySVG()}</div><div><div class="eyebrow">06 / مدن لها حكاية</div><h2>بغداد.<br>مدينة دائرية، وأثر يتجاوز الحدود.</h2><p>ادخل المدينة الدائرية التي بناها المنصور سنة 762 م، واضغط معالمها لتكتشف قصرها وجامعها وأبوابها الأربعة.</p><a class="primary" href="#/city">ادخل المدينة <span>←</span></a></div></div></section>
<section class="container section" style="padding-bottom:20px">${sectionTitle('07 / تحدَّ نفسك','هل تعرف متى ولمن؟','لعبتان قصيرتان: رتّب الأحداث زمنيًا، أو اختر الحضارة صاحبة الحدث.','#/play','كل الألعاب')}<div class="journey-grid"><a class="journey-card game-card" href="#/play/order"><span class="num">⧗</span><h3>رتّب الزمن</h3><p>أربعة أحداث مبعثرة؛ رتّبها من الأقدم إلى الأحدث.</p><span class="text-link">العب ←</span></a><a class="journey-card game-card" href="#/play/owner"><span class="num">◈</span><h3>لمن هذا الحدث؟</h3><p>عشرة أسئلة سريعة عن الحضارات وأحداثها.</p><span class="text-link">العب ←</span></a></div></section><section class="container section"><div class="fact"><span class="fact-mark">“</span><div id="fact-box"></div></div></section>`;renderFact();mountMap(false)}
const FACTS=[['لم تكن اليونان القديمة دولة واحدة.','كانت مئات المدن المستقلة، لكل منها حكومتها وجيشها، وأشهرها أثينا وإسبرطة.','greece'],['جيش من نحو ثمانية آلاف جندي من الطين يحرس قبر أول إمبراطور للصين.','اكتُشف قرب شيآن سنة 1974 م، ولكل جندي ملامح مختلفة.','qin-shi-huang'],['في سنة 929 م كان في العالم الإسلامي ثلاث خلافات في وقت واحد.','العباسية في بغداد، والفاطمية في شمال أفريقيا، والأموية في قرطبة.','cordoba-caliphate'],['بُنيت بغداد الأولى على شكل دائرة.','في وسطها قصر الخليفة والجامع، وحولها أسوار بأربعة أبواب.','baghdad'],['كلمة «خوارزمية» جاءت من اسم عالم عمل في بغداد.','هو محمد بن موسى الخوارزمي، في القرن التاسع الميلادي.','translation-movement'],['حكمت امرأة مصر ملكًا كامل الألقاب قبل 3500 عام.','هي حتشبسوت، وتُظهرها تماثيلها بلحية الملك الرسمية.','hatshepsut'],['أول إمبراطور روماني وُلد خارج إيطاليا هو تراجان.','وُلد في إيطاليكا بإقليم هسبانيا، وفي عهده بلغت الإمبراطورية أوسع امتداد لها.','trajan'],['مدينة واحدة كانت عاصمة لإمبراطوريتين.','القسطنطينية: عاصمة الروم من 330 م، ثم عاصمة العثمانيين من 1453 م.','constantinople-1453'],['تحتفل السعودية بيوم التأسيس في 22 فبراير.','تذكيرًا ببداية حكم الإمام محمد بن سعود في الدرعية سنة 1727 م.','saudi-found']];let factIdx=Math.floor(Math.random()*FACTS.length);
function renderFact(){const box=document.getElementById('fact-box');if(!box)return;const[f,t,id]=FACTS[factIdx%FACTS.length];box.innerHTML=`<div class="eyebrow">08 / هل تعلم؟</div><h3>${f}</h3><p>${t}</p><div class="actions"><a class="text-link" href="${href(id)}">اقرأ القصة ←</a><button class="fact-next" type="button">معلومة أخرى ↻</button></div>`;box.querySelector('.fact-next').onclick=()=>{factIdx++;renderFact()}}
