function nextReads(x){const pool=[...(x.related||[]),...(x.type==='civilization'?[]:[x.civId])].map(byId).filter(y=>y&&y.id!==x.id);const pick=[...new Map(pool.map(y=>[y.id,y])).values()].slice(0,3);if(!pick.length)return'';return `<section class="next-reads"><h2>اقرأ بعد ذلك</h2><div class="search-results">${pick.map(result).join('')}</div></section>`}
function bestFrame(c){let active=FRAMES.filter(y=>c.start<=y&&c.end>=y);return active[0]??nearestFrame(c.start)}
function timelinePage(params){const sel=params.get('civ')||'all';const evs=items.filter(x=>x.type==='event'&&(sel==='all'||x.civId===sel)).sort((a,b)=>a.start-b.start);let lastEra='';const era=y=>y<-500?'العالم القديم':y<0?'العصر الكلاسيكي':y<600?'القرون الميلادية الأولى':y<1300?'العصور الإسلامية الوسيطة':'بدايات العصر الحديث';setTimeout(()=>document.querySelector('.chip.active')?.scrollIntoView({inline:'center',block:'nearest'}),50);main.innerHTML=head('الخط الزمني','كل الأحداث مرتبة من الأقدم إلى الأحدث. اختر حضارة لترى قصتها وحدها.','متى حدث ذلك؟')+`<div class="container section" style="padding-top:0"><div class="filters">${[['all','كل الحضارات'],...civs.map(c=>[c.id,c.title])].map(([id,t])=>`<a href="#/timeline${id==='all'?'':'?civ='+id}" class="chip ${sel===id?'active':''}">${id==='all'?'':`<i style="background:${civColor(id)}"></i>`}${escape(t)}</a>`).join('')}</div><ol class="tl">${evs.map(e=>{const er=era(e.start),h=er!==lastEra?`<li class="tl-era">${er}</li>`:'';lastEra=er;return h+`<li class="tl-item" style="--c:${civColor(e.civId)}"><span class="tl-date">${escape(e.periodLabel)}</span><a href="${href(e.id)}"><h3>${escape(e.title)}</h3><p>${escape(e.summary.slice(0,150))}${e.summary.length>150?'…':''}</p><small>${escape(byId(e.civId)?.title||'')}${e.point?' · على الخريطة ⌖':''}</small></a></li>`}).join('')}</ol></div>`}
const GKEY='atlas-games';
function readGames(){try{const g=JSON.parse(storage.getItem(GKEY)||'{}');return{order:Number.isInteger(g.order)?g.order:0,owner:Number.isInteger(g.owner)?g.owner:0,where:Number.isInteger(g.where)?g.where:0}}catch{return{order:0,owner:0,where:0}}}
function saveGames(g){try{storage.setItem(GKEY,JSON.stringify(g))}catch{}}
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function playHub(){const g=readGames();main.innerHTML=head('تحدَّ نفسك','ثلاث ألعاب قصيرة تختبر ما تعرفه عن الزمن والمكان والحضارات. كل جولة أقل من دقيقتين.','العب وتعلّم')+`<div class="container section" style="padding-top:0"><div class="journey-grid"><a class="journey-card game-card" href="#/play/order"><span class="num">⧗</span><h3>رتّب الزمن</h3><p>أربعة أحداث مبعثرة. رتّبها من الأقدم إلى الأحدث، ثم اكتشف أين أصبت.</p><span class="muted">أفضل نتيجة: ${g.order} جولات كاملة متتالية</span><span class="text-link">ابدأ ←</span></a><a class="journey-card game-card" href="#/play/owner"><span class="num">◈</span><h3>لمن هذا الحدث؟</h3><p>عشرة أحداث، ولكل حدث ثلاث حضارات. اختر الحضارة التي وقع الحدث في تاريخها.</p><span class="muted">أفضل نتيجة: ${g.owner} من 10</span><span class="text-link">ابدأ ←</span></a><a class="journey-card game-card" href="#/play/where"><span class="num">⌖</span><h3>أين تقع؟</h3><p>نعطيك اسم مدينة تاريخية، وتضغط مكانها على الخريطة. كلما اقتربت زادت نقاطك.</p><span class="muted">أفضل نتيجة: ${g.where||0} من 500</span><span class="text-link">ابدأ ←</span></a></div></div>`}
function km(a,b){const R=6371,r=Math.PI/180,dl=(b[1]-a[1])*r,dn=(b[0]-a[0])*r,h=Math.sin(dl/2)**2+Math.cos(a[1]*r)*Math.cos(b[1]*r)*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
function playWhere(){const cities=shuffle(items.filter(x=>x.type==='city'&&x.point)).slice(0,5);let i=0,score=0,guess=null,map=null,pins=[];const tok=mountToken;main.innerHTML=head('أين تقع؟','اضغط على الخريطة حيث تظن أن المدينة تقع.','العب وتعلّم')+`<div class="container section game" style="padding-top:0"><div class="where-hud"><h2 class="where-q" id="where-q"></h2><span class="badge" id="where-score"></span></div><div id="map" class="where-map map-canvas map-loading" role="application" aria-label="خريطة لعبة أين تقع"></div><div id="where-fb" class="feedback" role="status" aria-live="polite"></div><div class="actions" id="where-act"></div></div>`;const pin=(p,cls,label)=>{const e=document.createElement('div');e.className='where-pin '+cls;if(label)e.innerHTML=`<span>${escape(label)}</span>`;const m=new maplibregl.Marker({element:e}).setLngLat(p).addTo(map);pins.push(m);markers.push(m)};const clear=()=>{for(const m of pins)m.remove();pins=[];if(map.getSource('halo'))map.getSource('halo').setData({type:'FeatureCollection',features:[]})};const ask=()=>{guess=null;clear();document.getElementById('where-q').textContent=`(${i+1}/5) أين تقع ${cities[i].title}؟`;document.getElementById('where-score').textContent=`النقاط ${score}`;document.getElementById('where-fb').textContent='';document.getElementById('where-act').innerHTML='';map.flyTo({center:[40,30],zoom:window.innerWidth<700?1.3:2,duration:reduced?0:600})};const finish=()=>{const g=readGames(),best=score>(g.where||0);if(best){g.where=score;saveGames(g)}document.getElementById('where-q').textContent=`نتيجتك: ${score} من 500`;document.getElementById('where-fb').innerHTML=(score>=400?'ممتاز! تعرف خريطة التاريخ جيدًا.':score>=250?'نتيجة جيدة.':'جرّب استكشاف الخريطة التاريخية ثم أعد المحاولة.')+(best?' <b class="gold">رقم قياسي جديد!</b>':'');document.getElementById('where-act').innerHTML='<button class="primary" data-again>جولة جديدة ←</button><a class="text-link" href="#/atlas">الخريطة التاريخية</a><a class="text-link" href="#/play">كل الألعاب</a>';document.querySelector('[data-again]').onclick=playWhere};const onClick=e=>{if(guess||i>=5)return;const c=cities[i];guess=[e.lngLat.lng,e.lngLat.lat];const d=Math.round(km(guess,c.point)),pts=d<=150?100:d<=400?80:d<=800?60:d<=1500?35:d<=2500?15:0;score+=pts;pin(guess,'guess');pin(c.point,'',c.title);map.getSource('halo')?.setData({type:'FeatureCollection',features:[{type:'Feature',geometry:{type:'LineString',coordinates:[guess,c.point]}}]});const b=new maplibregl.LngLatBounds();b.extend(guess);b.extend(c.point);map.fitBounds(b,{padding:70,maxZoom:5,duration:reduced?0:700});document.getElementById('where-score').textContent=`النقاط ${score}`;document.getElementById('where-fb').innerHTML=`${pts>=80?'رائع! ':pts>=35?'قريب. ':'بعيد قليلًا. '}المسافة نحو ${d.toLocaleString('ar')} كم · +${pts} نقطة. <a class="text-link" href="${href(c.id)}">اقرأ عن ${escape(c.title)}</a>`;document.getElementById('where-act').innerHTML=`<button class="primary" data-next>${i===4?'النتيجة':'التالي'} ←</button>`;document.querySelector('[data-next]').onclick=()=>{i++;i>=5?(clear(),finish()):ask()}};ensureMapLib().then(()=>{if(tok!==mountToken||!document.getElementById('map'))return;const el=document.getElementById('map');el.classList.remove('map-loading');const st=mapStyle();st.layers.push({id:'where-line',type:'line',source:'halo',paint:{'line-color':'#c5a46d','line-width':2,'line-dasharray':[2,2]}});map=liveMap=new maplibregl.Map({container:'map',dragRotate:false,pitchWithRotate:false,touchPitch:false,maxPitch:0,center:[40,30],zoom:window.innerWidth<700?1.3:2,minZoom:.6,maxZoom:7,renderWorldCopies:false,style:st});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');map.on('click',onClick);map.on('load',()=>{map.resize();ask()})}).catch(()=>{document.getElementById('where-fb').textContent='تعذّر تحميل الخريطة على هذا الجهاز.'})}
let orderStreak=0;
function playOrder(){const evs=items.filter(x=>x.type==='event');let pick;for(let t=0;t<50;t++){pick=shuffle(evs).slice(0,4);if(new Set(pick.map(e=>e.start)).size===4)break}const correct=[...pick].sort((a,b)=>a.start-b.start);let chosen=[];const draw=()=>{const done=chosen.length===4;const ok=done?chosen.map((e,i)=>e.id===correct[i].id):[];main.innerHTML=head('رتّب الزمن','اضغط الأحداث بالترتيب: الأقدم أولًا.','العب وتعلّم')+`<div class="container section game" style="padding-top:0"><div class="order-slots">${[0,1,2,3].map(i=>{const e=chosen[i];return `<div class="slot ${done?(ok[i]?'good':'bad'):''}"><b>${i+1}</b>${e?`<span>${escape(e.title)}</span>${done?`<small>${escape(e.periodLabel)}</small>`:''}`:'<span class="muted">…</span>'}</div>`}).join('')}</div>${done?'':`<div class="order-pool">${shuffle(pick).filter(e=>!chosen.includes(e)).map(e=>`<button data-pick="${escape(e.id)}" style="--c:${civColor(e.civId)}">${escape(e.title)}<small>${escape(byId(e.civId)?.title||'')}</small></button>`).join('')}</div>`}${done?`<div class="game-result"><h3>${ok.every(Boolean)?'ترتيب صحيح بالكامل! 🎉':`أصبت ${ok.filter(Boolean).length} من 4`}</h3><p>الترتيب الصحيح:</p><ol class="answer-list">${correct.map(e=>`<li><a href="${href(e.id)}"><b>${escape(e.periodLabel)}</b> ${escape(e.title)}</a></li>`).join('')}</ol><p class="muted">جولات كاملة متتالية: ${orderStreak}</p><div class="actions"><button class="primary" data-again>جولة جديدة ←</button><a class="text-link" href="#/play">كل الألعاب</a></div></div>`:`<div class="actions" style="margin-top:18px">${chosen.length?'<button data-undo>تراجع</button>':''}</div>`}</div>`;document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{chosen.push(pick.find(e=>e.id===b.dataset.pick));if(chosen.length===4){const all=chosen.every((e,i)=>e.id===correct[i].id);orderStreak=all?orderStreak+1:0;const g=readGames();if(orderStreak>g.order){g.order=orderStreak;saveGames(g)}}draw()});document.querySelector('[data-undo]')?.addEventListener('click',()=>{chosen.pop();draw()});document.querySelector('[data-again]')?.addEventListener('click',playOrder)};draw()}
function playOwner(){const evs=shuffle(items.filter(x=>x.type==='event'&&x.civId)).slice(0,10);let i=0,score=0,answered=null;const draw=()=>{if(i>=10){const g=readGames();const best=score>g.owner;if(best){g.owner=score;saveGames(g)}main.innerHTML=head('لمن هذا الحدث؟','انتهت الجولة.','العب وتعلّم')+`<div class="container section game" style="padding-top:0"><div class="game-result big"><h3>نتيجتك: ${score} من 10</h3><p>${score===10?'ممتاز! أصبت كل الأسئلة.':score>=7?'نتيجة قوية.':score>=4?'بداية جيدة؛ الخط الزمني سيساعدك.':'جرّب تصفح الخط الزمني ثم أعد المحاولة.'}${best?' <b class="gold">رقم قياسي جديد!</b>':''}</p><div class="actions"><button class="primary" data-again>جولة جديدة ←</button><a class="text-link" href="#/timeline">الخط الزمني</a><a class="text-link" href="#/play">كل الألعاب</a></div></div></div>`;document.querySelector('[data-again]').onclick=playOwner;return}const e=evs[i];const opts=shuffle([e.civId,...shuffle(civs.map(c=>c.id).filter(id=>id!==e.civId)).slice(0,2)]);main.innerHTML=head('لمن هذا الحدث؟',`السؤال ${i+1} من 10 · النتيجة ${score}`,'العب وتعلّم')+`<div class="container section game" style="padding-top:0"><div class="progress-track"><span style="width:${i*10}%"></span></div><div class="lesson-card"><span class="badge">${escape(e.periodLabel)}</span><h2>${escape(e.title)}</h2><div class="quiz-options">${opts.map(id=>`<button data-own="${id}" class="${answered?(id===e.civId?'correct':id===answered?'wrong':''):''}" ${answered?'disabled':''}><i class="civ-dot" style="background:${civColor(id)}"></i>${escape(byId(id).title)}</button>`).join('')}</div>${answered?`<div class="feedback">${answered===e.civId?'إجابة صحيحة. ':'الإجابة: '+escape(byId(e.civId).title)+'. '}${escape(e.summary.slice(0,160))}${e.summary.length>160?'…':''}</div><div class="actions"><button class="primary" data-next>${i===9?'النتيجة':'التالي'} ←</button><a class="text-link" href="${href(e.id)}" target="_self">اقرأ عن الحدث</a></div>`:''}</div></div>`;document.querySelectorAll('[data-own]').forEach(b=>b.onclick=()=>{answered=b.dataset.own;if(answered===e.civId)score++;draw()});document.querySelector('[data-next]')?.addEventListener('click',()=>{i++;answered=null;draw()})};draw()}
function journeys(){main.innerHTML=head('الرحلات التاريخية','تعلم بالفهم: افتح الموضوع، استكشف المكان، ثم أجب لتفتح المحطة التالية. تقدمك محفوظ محليًا في هذا المتصفح.')+`<div class="container section" style="padding-top:0"><div class="journey-grid">${JOURNEYS.map(journeyCard).join('')}</div></div>`}
function journey(id){const j=JOURNEYS.find(x=>x.id===id);if(!j)return notFound();const p=state.journeys[id]||{step:0,done:[]};p.step=validStep(p.step,j.steps.length);const N=j.steps.length;p.done=Array.isArray(p.done)?p.done.filter(v=>Number.isInteger(v)&&v>=0&&v<N):[];state.journeys[id]=p;const s=j.steps[p.step],c=byId(s.civ),key=`${id}:${p.step}`,answer=quizAnswers[key];main.innerHTML=head(j.title,j.subtitle,'رحلة تعليمية / تقدمك '+p.done.length+' من '+N)+`<div class="container section" style="padding-top:0"><div class="journey-workspace"><aside class="step-list">${j.steps.map((t,i)=>`<button data-step="${i}" class="${i===p.step?'active':''} ${p.done.includes(i)?'done':''}" ${i>0&&!p.done.includes(i-1)?'disabled':''}>${String(i+1).padStart(2,'0')} · ${t.title}</button>`).join('')}</aside><article class="lesson-card"><span class="badge">المحطة ${p.step+1} / ${N}</span><h2>${s.title}</h2><p>${s.text}</p><div class="context-graphic">${motif(s.civ)}<div><span class="gold">${s.when||dateLabel(s.year)}</span><p>${s.task}</p><div class="actions"><a class="text-link" href="${href(s.topic||s.civ)}">افتح الموضوع ←</a><a class="text-link" href="#/atlas?topic=${byId(s.topic)?.coordinates?s.topic:s.civ}&year=${s.topic&&s.year!=null?s.year:bestFrame(c)}">استكشف موقعه ⌖</a>${s.civ==='abbasid'?'<a class="text-link" href="#/city">ادخل بغداد ←</a>':''}</div></div></div><h3 style="margin-top:30px">${s.q}</h3><div class="quiz-options">${s.options.map((o,i)=>`<button data-journey-answer="${i}" class="${answer===i?(i===s.answer?'correct':'wrong'):''}">${o}</button>`).join('')}</div><div class="feedback" id="journey-feedback" role="status" aria-live="polite">${answer!==undefined?(answer===s.answer?'إجابة صحيحة. ':'حاول مجددًا. ')+s.explanation:p.done.includes(p.step)?'أكملت هذه المحطة سابقًا. يمكنك مراجعتها.':''}</div><div class="journey-actions"><button data-back ${p.step===0?'disabled':''}>→ المحطة السابقة</button>${p.step<N-1?`<button class="primary" data-next ${!p.done.includes(p.step)?'disabled':''}>المحطة التالية ←</button>`:`<a href="#/journeys" class="${p.done.includes(N-1)?'primary':'secondary'}">${p.done.includes(N-1)?'✓ أتممت الرحلة':'العودة للرحلات'}</a>`}</div></article></div></div>`;document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{p.step=+b.dataset.step;persist();journey(id)});document.querySelector('[data-back]').onclick=()=>{p.step--;persist();journey(id)};document.querySelector('[data-next]')?.addEventListener('click',()=>{if(p.done.includes(p.step)){p.step++;persist();journey(id)}});document.querySelectorAll('[data-journey-answer]').forEach(b=>b.onclick=()=>{const idx=+b.dataset.journeyAnswer;quizAnswers[key]=idx;if(idx===s.answer&&!p.done.includes(p.step)){p.done.push(p.step);persist()}journey(id)})}
const landmarks=[{title:'مركز الحكم',x:50,y:45,text:'يربط المخطط بين مركز المدينة ومقر الحكم. تخطيط المدينة المدورة وضع قصر الخليفة والجامع في قلبها. شكل القصر وألوانه في هذا الرسم رمزية، ولا تمثل أثرًا محفوظًا.',q:'ما وظيفة القصر؟',options:['مقر الحكم والإدارة','ميناء بحري','مزرعة خارج المدينة'],answer:0,explanation:'القصر يمثل مركز الحكم. تفاصيل تصميمه في هذا الرسم تعليمية وليست مسحًا أثريًا.'},{title:'الجامع',x:50,y:60,text:'الجامع جزء من مركز المدينة بحسب الروايات التي تستند إليها دراسات إعادة البناء. قربه من القصر يوضح حضور مؤسسات الحكم والعبادة في تخطيط العاصمة. لا يُفهم ترتيب الرسم على أنه قياس دقيق.',q:'ما الذي نستنتجه من رسم الجامع؟',options:['أن كل ارتفاعاته موثقة','وظيفته في المدينة، مع التحفظ على التفاصيل المرئية','أن الصورة تصوير فوتوغرافي'],answer:1,explanation:'الرسم يساعد على فهم الوظيفة. الأبعاد والارتفاعات ليست مثبتة بهذا المخطط.'},{title:'البوابات والاتصال',x:14,y:50,text:'أربع بوابات ربطت المدينة باتجاهات خارجية، وسميت في الروايات بالكوفة والبصرة والشام وخراسان. تمثل نقاط الدخول اتصال العاصمة بمحيطها، وليست حدود الدولة. هذا الرسم لا يثبت اتجاه كل بوابة.',q:'هل البوابة تحدد حدود الخلافة؟',options:['نعم','لا؛ هي مدخل للمدينة فقط','تحدد حدود العراق الحديثة'],answer:1,explanation:'البوابات عناصر في المدينة. حدود الخلافة مسألة جغرافية سياسية أوسع.'},{title:'الممرات والمناطق السكنية',x:64,y:30,text:'تساعد الممرات على ربط المركز بالبوابات والمناطق المحيطة. نمثل الأبنية الصغيرة هنا برموز تعليمية؛ عددها ومواقعها لا يدعيان مطابقة البناء القديم. توسعت بغداد مع الزمن خارج نواة المدينة المدورة.',q:'هل عدد الأبنية المرسومة إحصاء تاريخي؟',options:['نعم','نعم إذا تشابهت ألوانها','لا؛ هي رموز تعليمية'],answer:2,explanation:'العدد في الرسم قرار توضيحي، وليس بيانات أثرية أو تعدادًا للسكان.'}];
function city(selected=0){const l=landmarks[selected];main.innerHTML=head('بغداد: استكشف المدينة المدورة','تصور ثنائي الأبعاد يشرح وظائف المعالم. اختر النقاط أو استخدم الأزرار أدناه.','مدينة السلام / تأسست 762 م')+`<div class="container section" style="padding-top:0"><div class="city-workspace"><div><div class="city-scene">${citySVG()}${landmarks.map((t,i)=>`<button class="hotspot ${selected===i?'active':''}" style="left:${t.x}%;top:${t.y}%" data-landmark="${i}" aria-label="${t.title}">${state.city.includes(i)?'✓':i+1}</button>`).join('')}</div><div class="filters" style="margin-top:20px">${landmarks.map((t,i)=>`<button data-landmark="${i}" class="${selected===i?'active':''}">${t.title}</button>`).join('')}</div><small>فهمت ${state.city.length} من 4 معالم.</small><p class="map-note">رسم تعليمي مبسط للمدينة المدورة كما تصفها المصادر المكتوبة، وليس مخططًا أثريًا.</p></div><article class="landmark-detail" aria-live="polite"><span class="badge">${selected+1} / 4 · إعادة بناء تعليمية</span><h2 style="margin-top:18px">${l.title}</h2><p>${l.text}</p><h3>${l.q}</h3><div class="quiz-options">${l.options.map((o,i)=>`<button data-city-answer="${i}">${o}</button>`).join('')}</div><div id="city-feedback" class="feedback" role="status"></div><a class="text-link" href="${href('abbasid')}">اقرأ تاريخ العباسيين ←</a></article></div></div>`;document.querySelectorAll('[data-landmark]').forEach(b=>b.onclick=()=>city(+b.dataset.landmark));document.querySelectorAll('[data-city-answer]').forEach(b=>b.onclick=()=>{let good=+b.dataset.cityAnswer===l.answer;document.querySelectorAll('[data-city-answer]').forEach(v=>v.classList.remove('correct','wrong'));b.classList.add(good?'correct':'wrong');document.getElementById('city-feedback').textContent=(good?'أحسنت. ':'حاول مجددًا. ')+l.explanation;if(good&&!state.city.includes(selected)){state.city.push(selected);persist();document.querySelectorAll('[data-landmark]').forEach(v=>{if(v.classList.contains('hotspot')&&+v.dataset.landmark===selected)v.textContent='✓'});document.querySelector('.city-workspace small').textContent=`فهمت ${state.city.length} من 4 معالم.`}})}
function saved(){const list=items.filter(x=>state.saved.includes(x.id));main.innerHTML=head('محفوظاتي','مساحة خاصة للموضوعات التي تريد العودة إليها. تُحفظ في هذا المتصفح فقط، وليست حسابًا سحابيًا.')+`<div class="container section" style="padding-top:0">${list.length?`<div class="search-results">${list.map(result).join('')}</div>`:'<div class="empty"><h3>ابدأ مجموعتك التاريخية.</h3><p>افتح أي موضوع واضغط «احفظ الموضوع» لتجده هنا لاحقًا.</p><a class="primary" href="#/encyclopedia">استكشف الموسوعة ←</a></div>'}</div>`}
function sourcesPage(){const n=t=>items.filter(x=>x.type===t).length,st=window.__STATS||{},noB=FRAMES.filter(y=>!BORDER_YEARS.includes(y)),ims=[...new Map(items.filter(x=>x.image).map(x=>[x.image.file,x.image])).values()];main.innerHTML=head('منهجنا','كيف نكتب صفحات أطلس، ومن أين نأخذ المعلومات، وكيف نراجعها، وما حدود ما نعرضه.')+`<div class="container section article-text" style="padding-top:0">
<section><h2>ما أطلس؟</h2><p>أطلس مشروع تعليمي عربي مستقل يربط التاريخ بالمكان والزمن. يضم ${items.length} صفحة: ${civs.length} حضارة ودولة، و${n('city')} مدينة، و${n('person')} شخصية، و${n('event')} حدثًا، و${n('science')} صفحة في العلوم. ويركّز على تاريخ العرب والمسلمين، مع حضارات العالم الكبرى التي عاصرتهم أو سبقتهم. وهو لا يدّعي أنه يغطي التاريخ كله.</p></section>
<section><h2>من أين نأخذ المعلومات؟</h2><p>كل صفحة مكتوبة بالعربية خصيصًا لأطلس، ولكل قسم فيها مصدر واحد على الأقل. ونرجع إلى ${st.sources||'مئات'} مصدرًا، أكثرها: الموسوعة البريطانية (بريتانيكا)، وقوائم التراث العالمي في اليونسكو، ومتاحف كبرى مثل متحف المتروبوليتان، وويكيبيديا للتحقق المبدئي ولا نعتمد عليها وحدها في المسائل الخلافية. وفي تاريخ المملكة العربية السعودية نرجع إلى المراجع الرسمية الموثقة، ومنها دارة الملك عبدالعزيز وسعوديبيديا.</p><p>لا نعرض قائمة المصادر في كل صفحة حتى تبقى القراءة سهلة، لكنها محفوظة مع كل قسم في بيانات الموقع.</p></section>
<section><h2>كيف نراجع؟</h2><p>تمر كل دفعة من الصفحات الجديدة، قبل نشرها، على مراجعة مستقلة يجريها نموذج ذكاء اصطناعي آخر لم يكتب النص: يفتح المصادر، ويقارن كل تاريخ واسم ورقم ومكان، ويتحقق من أن روابط المصادر تعمل، وأن الإحداثيات تقع في مكانها، وأن العبارات محايدة في المسائل الدينية والمذهبية. وفي التوسعة الأخيرة وحدها طُبّقت أكثر من مئتي ملاحظة من هذه المراجعات. ثم تُفحص الصفحات آليًا بأكثر من ألف وستمئة اختبار قبل النشر.</p><p>لم يراجع مؤرخ متخصص جميع النصوص بعد، فقد يبقى فيها خطأ أو تبسيط. ونصحح ما نجده في كل تحديث.</p></section>
<section><h2>كيف نكتب التواريخ واليقين؟</h2><p>التواريخ ميلادية، ونذكر معها الهجري في أحداث التاريخ الإسلامي. ونكتب «ق.م» لما قبل الميلاد، و«نحو» للتاريخ التقريبي. وإذا اختلفت المصادر في سنة أو رقم ذكرنا الاختلاف بدل اختيار رقم واحد، وفي كثير من الصفحات قسم بعنوان «روايات مختلفة».</p><div class="notice">في أسفل الصفحات وصف لدرجة التوثيق: <b>موثق</b> تتفق عليه المصادر. <b>تقريبي</b> التاريخ أو الموضع تقدير عام. <b>موضع خلاف</b> تختلف فيه المصادر أو المؤرخون. والروايات المتأخرة والأساطير المشهورة نذكرها بصيغة «تروي المصادر» لا بصيغة الخبر المؤكد.</div></section>
<section><h2>كيف نرسم الخريطة؟</h2><p>للخريطة ${FRAMES.length} لقطة زمنية. في ${BORDER_YEARS.length} منها حدود تقريبية من مشروع <a class="text-link" href="https://github.com/aourednik/historical-basemaps" target="_blank" rel="noopener">Historical Basemaps</a> المفتوح، بعد تعريب أسمائها وتصحيح ما وجدناه من أخطاء زمنية فيها. وتركنا بلا حدود اللقطات التي لم نجد لها بيانات موثوقة: ${noB.map(dateLabel).join('، ')}. والحدود في العصور القديمة والوسطى تقريبية بطبيعتها، فلم تكن للدول خطوط حدود كما نعرفها اليوم. وإذا تداخل مضلعا دولتين في المصدر جعلنا المنطقة المشتركة للدولة الأصغر، وقصصنا الحدود على اليابسة فلا تمتد فوق البحار، ولا نضيف حدودًا من عندنا.</p><p>علامات المدن مرتبطة بالحضارة الظاهرة في اللقطة. وتعرض طبقة الأحداث أحدث أحداث كل حضارة في اللقطة، حتى لا تزدحم الخريطة. واليابسة والأنهار والجليد من بيانات Natural Earth المعاصرة، فلا تظهر تغيرات السواحل ومجاري الأنهار عبر الزمن. وظلال الجبال من بيانات الارتفاعات المفتوحة Terrain Tiles للعالم كله. وألوان الأرض (الصحارى والسهوب والغابات والتندرا) من تصنيف المناطق الحيوية <a class="text-link" href="https://ecoregions.appspot.com/" target="_blank" rel="noopener">RESOLVE Ecoregions 2017</a> (رخصة CC BY 4.0)، وهو يصف الغطاء النباتي اليوم لا في كل عصر، وإن كانت الصحارى الكبرى على حالها في الفترة التي يغطيها الأطلس. والخريطة الصغيرة في كل صفحة مبنية على البيانات نفسها.</p></section>
<section><h2>الصور</h2><p>الصور الفوتوغرافية من ويكيميديا كومنز برخص مفتوحة أو ملكية عامة، وأسماء المصوّرين والرخص في القائمة أدناه، وعلامة © تحت كل صورة تفتح صفحتها الأصلية، وتحققنا منها كلها من صفحة الصورة نفسها. ولا نعرض أي صورة متخيلة للنبي ﷺ أو للصحابة رضي الله عنهم: نستعمل بدلها صور المساجد والمواقع، ولوحات أسمائهم بالخط العربي، والنقود والمخطوطات. وصورة الصفحة الرئيسية تصور فني لا يمثل مكانًا بعينه.</p><details><summary>قائمة الصور ومصوّريها (${ims.length})</summary><ul class="source-list">${ims.map(im=>`<li><a href="${escape(im.page)}" target="_blank" rel="noopener">${escape(im.caption)} ↗</a><small>${escape(im.author)} · ${escape(im.license)}</small></li>`).join('')}</ul></details></section>
<section><h2>الخصوصية</h2><p>لا يحتاج الموقع إلى حساب. المحفوظات ونتائج الألعاب تُحفظ في متصفحك فقط، وتُمحى إذا مسحت بيانات المتصفح. ويحفظ الموقع ملفات الخريطة الكبيرة على جهازك ليسرع فتحها في المرة التالية.</p></section>
<section><h2>الأدوات ورخصها</h2><p><a class="gold" target="_blank" rel="noopener" href="https://www.naturalearthdata.com/about/terms-of-use/">Natural Earth: ملكية عامة ↗</a> · <a class="gold" target="_blank" rel="noopener" href="https://github.com/aourednik/historical-basemaps">Historical Basemaps: GPL-3.0 ↗</a> · <a class="gold" target="_blank" rel="noopener" href="https://ecoregions.appspot.com/">RESOLVE Ecoregions 2017: CC BY 4.0 ↗</a> · <a class="gold" target="_blank" rel="noopener" href="https://registry.opendata.aws/terrain-tiles/">Terrain Tiles (Mapzen وUSGS وغيرهما): بيانات مفتوحة ↗</a> · <a class="gold" href="assets/MAPLIBRE-LICENSE.txt">MapLibre GL JS 5.6.1: BSD-3-Clause</a> · <a class="gold" href="assets/FONT-LICENSE.txt">IBM Plex Sans Arabic: SIL Open Font License</a></p></section></div>`}
const researchRows=[['GeaCron','أطلس منذ 3000 ق.م؛ ممالك ومعارك وحملات وقاعدة خرائط متجهة.','التطبيق مضمن داخل iframe؛ لم تُختبر تفاعلاته.','https://geacron.com/home-en/'],['TimeMaps','تتابع خرائط عالمي وإقليمي ومحلي، ومراجع تعليمية، و20 تاريخًا مشتركًا.','تعذر تحميل الرئيسية؛ وصلت صفحة شرح الأطلس.','https://timemaps.com/the-timemaps-atlas-of-world-history/'],['Chronas','النتيجة التعريفية تذكر اشتراط WebGL.','صفحة التطبيق الحالية فارغة في القراءة؛ التفاعل غير مفحوص.','https://www.chronas.org/'],['World History Encyclopedia','موسوعة وخرائط وخط زمني ومصادر أولية وسياسة تحرير.','فحص صفحات عامة؛ لا قياس للنتائج التعليمية.','https://www.worldhistory.org/static/editorial-policy/'],['World-Civ','سحب وتشغيل الزمن، مناطق قابلة للنقر، مرشحات، وأحداث؛ رخص ومصادر ظاهرة.','تحقق من وصف الصفحة، دون تجربة الخريطة.','https://world-civ.com/'],['Geographic History','صفحة عربية تصف خرائط سنوية وأحداثًا وألعاب جغرافية.','الوصف يخص تطبيق الهاتف؛ لم يُثبت تكافؤ تجربة الويب.','https://geographichistory.app/ar/'],['Atlas Anatolia','مواقع أثرية وعصور ورحلات وإعادة بناء وتقييم للأدلة.','الأقسام موجودة في النص؛ وظائفها لم تُختبر بالمتصفح.','https://atlasanatolia.com/ar'],['بوابات التاريخ','بحث عربي ومسطرة زمنية ومقالات وقادة ومعارك.','ظهر Loading للخريطة في النص، وأعداد المقالات غير متسقة.','https://gatesofhistory.com/ar']];
function researchPage(){main.innerHTML=head('ما الذي تعلمناه من المنافسين؟','مقارنة عملية قبل التنفيذ · 12 أكتوبر 2026 · فحص صفحات عامة، وليس اختبار استخدام كاملًا.')+`<div class="container section article-text" style="padding-top:0"><div class="table-wrap"><table><thead><tr><th>الموقع</th><th>الميزة التي تحققنا منها</th><th>حدود الفحص</th></tr></thead><tbody>${researchRows.map(r=>`<tr><td><a href="${r[3]}" target="_blank" rel="noopener">${r[0]} ↗</a></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div><section><h2>أفضل خمس أفكار</h2><ol><li>ربط الموقع والفترة والموضوع (TimeMaps).</li><li>عنصر زمن واضح بجانب الخريطة (GeaCron وWorld-Civ).</li><li>تمييز درجة اليقين والتصور الفني (Atlas Anatolia).</li><li>تنظيم الموضوعات والمراجع والمواد التعليمية (WHE).</li><li>بحث عربي يتصل بالموسوعة والخريطة (بوابات التاريخ).</li></ol></section><section><h2>مشكلات مرصودة وتوصيات</h2><p>يوضح TimeMaps أن الفجوات بين لقطاته قد تتجاوز أحداثًا كبيرة؛ لذلك أضفنا رحلات تشرح التحول. اشتراط WebGL قد يحد الوصول في بعض البيئات؛ لذلك وفرنا قائمة المواقع وعرضًا بديلًا. ظهرت أعداد مقالات متباينة في صفحة بوابات التاريخ؛ لذلك نحسب أعداد ATLAS من بياناته الفعلية.</p><p>ازدحام الأقسام قد يربك البداية، لكنه استنتاج تصميمي هنا لا نتيجة اختبار مستخدم. اخترنا أربع وجهات رئيسية ومراجع داخل كل موضوع.</p></section><section><h2>فرص التميز الواقعية</h2><p>الخريطة والرحلات والأسئلة وإعادة البناء موجودة لدى منافسين. التميز المقترح ليس اختراعها، بل تجربة عربية متماسكة، تعليم مختصر، بيانات محدودة صادقة، وأسئلة تفسر أخطاء الفهم. لم نقس الأثر التعليمي بعد.</p></section><section><h2>كيف انعكست الدراسة على التنفيذ؟</h2><p>لقطات زمنية محددة بدل شريط يوحي ببيانات لكل سنة. نقاط مدن، وحدود تقريبية من مصدر مفتوح مذكورة سنتها، بدل حدود مختلقة. مراجع بجانب الفقرات. تقدم يحفظ بعد إجابة صحيحة، ومخطط يميز الفن عن الدليل الأثري. لم ننسخ تصميمًا أو أصلًا أو محتوى من هذه المنصات.</p><a class="text-link" href="COMPETITOR_RESEARCH.md">اقرأ التقرير التفصيلي ←</a></section></div>`}
function notFound(){main.innerHTML=head('الموضوع غير موجود','قد يكون الرابط غير صحيح. يمكنك البحث عن الموضوع أو العودة إلى الموسوعة.')+'<div class="container section"><a class="primary" href="#/encyclopedia">الموسوعة ←</a></div>'}
function route(){mountToken++;clearBorderLabels();clearInterval(playTimer);playTimer=null;for(const m of markers)m.remove();markers=[];for(const m of geoMarkers)m.remove();geoMarkers=[];if(liveMap){liveMap.remove();liveMap=null}const hash=location.hash.slice(1)||'/',[path,query]=hash.split('?'),parts=path.split('/').filter(Boolean),params=new URLSearchParams(query||'');document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href').split('/')[1]===parts[0]));switch(parts[0]){case undefined:if(window.__TOPIC){article(window.__TOPIC);break}if(window.__INDEX){document.title=main.querySelector('h1')?.textContent+' | أطلس';return}home();warmMap();break;case'atlas':atlas(params);break;case'encyclopedia':ensureText();encyclopedia(params);break;case'search':ensureText();encyclopedia(params,true);break;case'topic':article(decodeURIComponent(parts[1]||''));break;case'journeys':journeys();break;case'timeline':timelinePage(params);break;case'play':parts[1]==='order'?playOrder():parts[1]==='owner'?playOwner():parts[1]==='where'?playWhere():playHub();break;case'journey':journey(parts[1]);break;case'city':city();break;case'saved':saved();break;case'sources':case'method':sourcesPage();break;case'research':researchPage();break;default:notFound()}if(!reduced&&window.IntersectionObserver){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('reveal');observer.unobserve(e.target)}},{threshold:.08});document.querySelectorAll('main>.section,main>.container.section').forEach(el=>observer.observe(el))}window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});document.title=`${main.querySelector('h1')?.textContent||'اكتشف العالم عبر الزمن'} | أطلس`}
function adapt(raw){window.__STATS=raw.stats||{};sources=Object.fromEntries(raw.sources.map(s=>[s.id,s]));civs=raw.civilizations.map(c=>({...c,start:c.startYear,end:c.endYear,point:c.coordinates,periodLabel:c.period,sources:c.sourceIds,related:[c.cityId,...c.events.filter(e=>raw.entries.some(x=>x.id===e.id)).map(e=>e.id),...c.people.map(p=>p.id)]}));items=[...civs,...raw.entries.map(x=>{const c=civs.find(c=>c.cityId===x.id||c.people.some(p=>p.id===x.id)||c.events.some(e=>e.id===x.id)||x.relatedIds?.includes(c.id));return {...x,start:x.startYear||x.year||c?.start||-1,end:x.endYear||x.year||c?.end||1,point:x.coordinates,region:x.region||c?.region,civId:c?.id,periodLabel:x.period||x.dateLabel||(x.year?dateLabel(x.year):c?.periodLabel)||'انظر الموضوع',sources:x.sourceIds,related:x.relatedIds||[],sections:x.sections||[]}})];sources['city-archnet']={id:'city-archnet',title:'Archnet — Al-Mansur’s Round City of Baghdad',url:'https://www.archnet.org/sites/3826',type:'مرجع معماري؛ الصفحة المباشرة حجبت الوصول أثناء الفحص'};sources['city-cambridge']={id:'city-cambridge',title:'IRAQ — Images of Round Baghdad: An Analysis of Reconstructions',url:'https://www.cambridge.org/core/journals/iraq/article/images-of-round-baghdad-an-analysis-of-reconstructions-by-architectural-historians/8BD21CCA3B37DB2906D47749F0C0A99F',type:'دراسة أكاديمية؛ اطلعنا على الملخص'};sources['city-khan']={id:'city-khan',title:'Khan Academy — The founding of Baghdad',url:'https://www.khanacademy.org/humanities/art-islam/chronological-periods-islamic/islamic-art-medieval/a/the-founding-of-baghdad',type:'مادة تعليمية'};validateContent(items,sources)}
document.querySelector('.menu-toggle').onclick=e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))};
