// المحتوى على دفعتين: الأساس (العناوين والتواريخ والمواقع) فيظهر الموقع والخريطة سريعًا، ثم نصوص الأقسام في الخلفية
let textLoaded=false,textP=null;const getJSON=u=>fetch(u).then(r=>{if(!r.ok)throw Error('content loading');return r.json()});
function mergeText(t){for(const x of items)if(t[x.id])x.sections=t[x.id];textLoaded=true}
const ensureText=()=>textP||(textP=getJSON('content-text.json').then(mergeText).catch(()=>getJSON('content.json').then(full=>mergeText(Object.fromEntries([...full.civilizations,...full.entries].map(x=>[x.id,x.sections||[]]))))));
// النصوص لا تلزم الخريطة: نطلبها بعد أن تهدأ الصفحة، أو فورًا عند فتح موضوع أو بحث
const idleText=()=>setTimeout(()=>{const go=()=>(window.requestIdleCallback||(f=>f()))(ensureText),end=Date.now()+8000,w=()=>{const m=window.__atlasMap;if(!/^#\/atlas/.test(location.hash)||Date.now()>end||(m&&m.loaded()))return go();if(m){let done=0;const f=()=>{if(!done){done=1;setTimeout(go,400)}};m.once('idle',f);setTimeout(f,Math.max(0,end-Date.now()))}else setTimeout(w,400)};w()},2500);
getJSON('content-core.json').then(raw=>{if(document.readyState==='complete')idleText();else addEventListener('load',idleText);return raw},()=>getJSON('content.json').then(raw=>{textLoaded=true;textP=Promise.resolve();return raw})).then(raw=>{DATA=raw;adapt(raw);window.addEventListener('hashchange',route);route()}).catch(e=>{console.error(e);main.innerHTML='<div class="container section empty"><h1>تعذر تحميل المحتوى.</h1><p>أعد المحاولة. إذا استمر الخطأ تحقق من اتصالك.</p><button id="retry">أعد المحاولة</button></div>';document.getElementById('retry').onclick=()=>location.reload()});
